<?php
require_once __DIR__.'/includes/bootstrap.php'; require_login(); $u=current_user(); $number=trim($_GET['order']??''); $error=''; $notice=''; $order=null; $items=[];
if($db&&$number){$st=$db->prepare('SELECT * FROM orders WHERE order_number=? AND user_id=? LIMIT 1');$st->execute([$number,$u['id']]);$order=$st->fetch();if($order){$st=$db->prepare('SELECT * FROM order_items WHERE order_id=?');$st->execute([$order['id']]);$items=$st->fetchAll();}}
$hasDomain=false;foreach($items as $it){if($it['item_type']==='domain'){$hasDomain=true;break;}}
$ageOk=$order ? ((time()-strtotime($order['created_at'])) <= 30*86400) : false;
if(is_post() && $order){verify_csrf();public_form_guard($db, 'refund', $_POST['recaptcha_token'] ?? '');$reason=trim($_POST['reason']??'');if($hasDomain)$error='Domain purchases are excluded from the 30-day money-back credit policy.';elseif(!$ageOk)$error='This order is outside the 30-day refund window.';elseif(!in_array($order['status'],['paid','active'],true))$error='Only paid or active orders can be submitted for a refund.';elseif(!$reason)$error='Please provide a reason.';else{try{$st=$db->prepare("SELECT COUNT(*) FROM refunds WHERE order_id=? AND status IN ('requested','approved')");$st->execute([$order['id']]);if((int)$st->fetchColumn()>0)throw new RuntimeException('A refund request already exists for this order.');$st=$db->prepare('INSERT INTO refunds(order_id,user_id,amount,reason) VALUES(?,?,?,?)');$st->execute([$order['id'],$u['id'],$order['total'],$reason]);$notice='Refund request submitted. If approved, the eligible amount will be credited to your WDH Account Balance.';}catch(Throwable $e){$error=$e->getMessage();}}}
?><!doctype html><html lang="<?=e($LANG)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Refund Request — WDH</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="simple-page"><div class="breadcrumbs">Home › Client Portal › Refund</div><?php if(!$order):?><div class="empty"><h1>Order Not Found</h1><a class="btn primary" href="invoices.php">Back to Invoices</a></div><?php else:?><section class="auth-card" style="max-width:760px"><span class="eyebrow mint">30-DAY MONEY-BACK POLICY</span><h1>Request Account Credit</h1><p>Order <strong><?=e($order['order_number'])?></strong> · <?=money($order['total'],$order['currency'])?></p><?php if($notice):?><div class="alert success-alert"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><p class="muted">Eligible non-domain services may be reviewed within 30 days. Approved refunds are credited to your WDH Account Balance rather than returned as cash.</p><form method="post"><?=csrf_field()?><input type="text" name="website" value="" class="hp-field" tabindex="-1" autocomplete="off" aria-hidden="true"><?=recaptcha_field('refund')?><label>Reason<textarea name="reason" rows="5" required placeholder="Tell us why you are cancelling this service..."></textarea></label><button class="btn primary" <?=$hasDomain||!$ageOk?'disabled':''?>>Submit Refund Request</button></form></section><?php endif;?></main><?php require __DIR__.'/includes/footer.php';?></body></html>
